/**
 * CairnNZ app-owned text catalog.
 *
 * OWNER EDITABLE: this is the only hand-maintained source for app display
 * copy. Runtime helpers and audit reports are derived consumers, not parallel
 * translation catalogs. `null` means that Japanese is deliberately pending
 * and must fall back to the complete New Zealand English source.
 */

export type CairnCatalogLocale = 'en-NZ' | 'ja-JP';
export type CairnTranslationStatus = 'source' | 'approved' | 'draft' | 'pending';
export type CairnTextParameterType = 'string' | 'number' | 'date';
export type CairnPluralText = {
  zero?: string;
  one: string;
  other: string;
};

export interface CairnTextEntry {
  'en-NZ': string | CairnPluralText;
  'ja-JP': string | CairnPluralText | null;
  /** Meaning and translator guidance; never used as runtime copy. */
  context: string;
  /** Reachable screens, dialogs, notifications or diagnostic surfaces. */
  surfaces: readonly string[];
  /** Named interpolation values and their required semantic types. */
  params: Readonly<Record<string, CairnTextParameterType>>;
  /** Constraints that affect wrapping, truncation or accessibility. */
  layout: string;
  translationStatus: Readonly<Record<CairnCatalogLocale, CairnTranslationStatus>>;
}

